OUTPUT_SUMMARY = "eurgbp_candidateB_portfolio_substitution_summary.csv"
OUTPUT_5Y = "eurgbp_candidateB_portfolio_five_year_trades.csv"
OUTPUT_2Y = "eurgbp_candidateB_portfolio_two_year_trades.csv"

STATUS = {
    "state": "not_started",
    "message": "Analysis has not started",
    "orders_supported": False,
    "trading_enabled": False,
}


def read_csv_text(text):
    df = pd.read_csv(
        io.StringIO(text)
    )

    for col in [
        "entry_time_utc",
        "exit_time_utc",
    ]:
        df[col] = pd.to_datetime(
            df[col],
            utc=True,
        )

    df["result_r"] = pd.to_numeric(
        df["result_r"],
        errors="coerce",
    )

    return df


def restrict_window(
    df,
    start,
    end,
):
    return df[
        (df["entry_time_utc"] >= start)
        &
        (df["entry_time_utc"] <= end)
    ].copy()


def replace_pair_side(
    portfolio,
    replacement,
    instrument,
    side,
    start,
    end,
):
    kept = portfolio[
        ~(
            (portfolio["instrument"] == instrument)
            &
            (portfolio["side"] == side)
        )
    ].copy()

    incoming = restrict_window(
        replacement,
        start,
        end,
    )

    out = pd.concat(
        [kept, incoming],
        ignore_index=True,
    )

    return (
        out.sort_values(
            [
                "entry_time_utc",
                "exit_time_utc",
                "instrument",
                "side",
            ]
        )
        .reset_index(drop=True)
    )


def stats(df):
    r = df["result_r"].astype(float)

    winners = r[r > 0]
    losers = r[r < 0]

    gp = winners.sum()
    gl = abs(losers.sum())

    pf = (
        gp / gl
        if gl > 0
        else (
            999.0
            if gp > 0
            else 0.0
        )
    )

    total = r.sum()

    return {
        "trades": len(df),
        "winners": len(winners),
        "losers": len(losers),
        "win_rate": (
            len(winners)
            / len(df)
            * 100.0
            if len(df)
            else 0.0
        ),
        "profit_factor": pf,
        "total_r": total,
        "expectancy_r": (
            total / len(df)
            if len(df)
            else 0.0
        ),
    }


def compound(
    df,
    starting_balance=100.0,
    risk_percent=0.01,
):
    records = (
        df.reset_index(drop=True)
        .to_dict("records")
    )

    events = []

    for i, trade in enumerate(records):
        events.append((
            pd.Timestamp(
                trade["entry_time_utc"]
            ).to_pydatetime(),
            1,
            "ENTRY",
            i,
        ))

        events.append((
            pd.Timestamp(
                trade["exit_time_utc"]
            ).to_pydatetime(),
            0,
            "EXIT",
            i,
        ))

    # EXIT before ENTRY at same timestamp.
    events.sort(
        key=lambda x: (
            x[0],
            x[1],
        )
    )

    balance = float(
        starting_balance
    )

    risk_at_entry = {}

    peak = balance
    max_dd_pct = 0.0

    for (
        event_time,
        priority,
        event_type,
        i,
    ) in events:
        trade = records[i]

        if event_type == "ENTRY":
            risk_at_entry[i] = (
                balance
                * risk_percent
            )

        else:
            risk_amount = (
                risk_at_entry.get(i)
            )

            if risk_amount is None:
                continue

            balance += (
                risk_amount
                * float(
                    trade["result_r"]
                )
            )

            peak = max(
                peak,
                balance,
            )

            if peak > 0:
                dd = (
                    (
                        balance
                        - peak
                    )
                    / peak
                    * 100.0
                )

                max_dd_pct = min(
                    max_dd_pct,
                    dd,
                )

    return {
        "ending_balance": balance,
        "return_pct": (
            balance
            / starting_balance
            - 1.0
        ) * 100.0,
        "max_closed_equity_dd_pct": (
            max_dd_pct
        ),
    }


def summary_row(
    window,
    name,
    df,
):
    s = stats(df)
    c = compound(df)

    return {
        "window": window,
        "portfolio": name,
        "trades": s["trades"],
        "winners": s["winners"],
        "losers": s["losers"],
        "win_rate": round(
            s["win_rate"],
            6,
        ),
        "profit_factor": round(
            s["profit_factor"],
            9,
        ),
        "total_r": round(
            s["total_r"],
            6,
        ),
        "expectancy_r": round(
            s["expectancy_r"],
            9,
        ),
        "ending_balance_1pct": round(
            c["ending_balance"],
            6,
        ),
        "return_pct_1pct": round(
            c["return_pct"],
            6,
        ),
        "max_closed_equity_dd_pct": round(
            c[
                "max_closed_equity_dd_pct"
            ],
            6,
        ),
    }


def export_versions(
    filename,
    window,
    current,
    proposed,
):
    a = current.copy()
    a["portfolio_version"] = (
        "CURRENT_AFTER_USDCAD_REPLACEMENT"
    )

    b = proposed.copy()
    b["portfolio_version"] = (
        "NEW_WITH_EURGBP_CANDIDATE_B"
    )

    out = pd.concat(
        [a, b],
        ignore_index=True,
    )

    out["window"] = window

    for col in [
        "entry_time_utc",
        "exit_time_utc",
    ]:
        out[col] = (
            out[col]
            .dt.strftime(
                "%Y-%m-%dT%H:%M:%SZ"
            )
        )

    out.to_csv(
        os.path.abspath(filename),
        index=False,
    )


def run_analysis():
    try:
        STATUS.update({
            "state": "loading",
            "message": (
                "Loading embedded validated logs"
            ),
        })

        base5 = read_csv_text(BASE5)
        base2 = read_csv_text(BASE2)
        usdcad = read_csv_text(USDCAD_B)
        eurgbp = read_csv_text(EURGBP_B)

        summary = []

        for (
            window,
            original,
            export_name,
        ) in [
            (
                "5Y",
                base5,
                OUTPUT_5Y,
            ),
            (
                "2Y",
                base2,
                OUTPUT_2Y,
            ),
        ]:
            STATUS.update({
                "state": "calculating",
                "message": (
                    f"Calculating {window}"
                ),
            })

            start = original[
                "entry_time_utc"
            ].min()

            end = original[
                "entry_time_utc"
            ].max()

            # Rebuild current portfolio with the USD/CAD
            # Candidate B replacement already applied.
            current = replace_pair_side(
                original,
                usdcad,
                "USD_CAD",
                "BUY",
                start,
                end,
            )

            # Proposed EUR/GBP Candidate B replacement.
            proposed = replace_pair_side(
                current,
                eurgbp,
                "EUR_GBP",
                "BUY",
                start,
                end,
            )

            before = summary_row(
                window,
                "CURRENT_AFTER_USDCAD_REPLACEMENT",
                current,
            )

            after = summary_row(
                window,
                "NEW_WITH_EURGBP_CANDIDATE_B",
                proposed,
            )

            summary.extend(
                [before, after]
            )

            delta = {
                "window": window,
                "portfolio": (
                    "CHANGE_NEW_MINUS_CURRENT"
                ),
            }

            for col in [
                "trades",
                "winners",
                "losers",
                "win_rate",
                "profit_factor",
                "total_r",
                "expectancy_r",
                "ending_balance_1pct",
                "return_pct_1pct",
                "max_closed_equity_dd_pct",
            ]:
                delta[col] = round(
                    after[col]
                    - before[col],
                    9,
                )

            summary.append(
                delta
            )

            export_versions(
                export_name,
                window,
                current,
                proposed,
            )

        summary_df = pd.DataFrame(
            summary
        )

        summary_df.to_csv(
            os.path.abspath(
                OUTPUT_SUMMARY
            ),
            index=False,
        )

        STATUS.update({
            "state": "complete",
            "message": (
                "EUR/GBP Candidate B portfolio substitution complete"
            ),
            "outputs": {
                "summary": OUTPUT_SUMMARY,
                "5y": OUTPUT_5Y,
                "2y": OUTPUT_2Y,
            },
        })

        print()
        print("=" * 95)
        print(
            "EUR/GBP CANDIDATE B PORTFOLIO SUBSTITUTION"
        )
        print("=" * 95)
        print(
            summary_df.to_string(
                index=False
            ),
            flush=True,
        )

    except Exception as exc:
        STATUS.update({
            "state": "error",
            "message": str(exc),
        })

        print(
            "ERROR:",
            exc,
            flush=True,
        )


@app.route("/")
def home():
    return jsonify({
        "service": (
            "EUR/GBP Candidate B Portfolio Substitution"
        ),
        "status": STATUS,
        "mode": "READ_ONLY_RESEARCH",
        "orders_supported": False,
        "trading_enabled": False,
        "downloads": {
            "summary": "/download/summary",
            "five_year": "/download/5y",
            "two_year": "/download/2y",
        },
    })


@app.route("/status")
def status():
    return jsonify(
        STATUS
    )


def send_output(filename):
    path = os.path.abspath(
        filename
    )

    if not os.path.exists(path):
        return jsonify({
            "status": "not_ready",
            "message": (
                f"{filename} is not ready yet"
            ),
        }), 404

    return send_file(
        path,
        as_attachment=True,
        download_name=filename,
    )


@app.route("/download/summary")
def download_summary():
    return send_output(
        OUTPUT_SUMMARY
    )


@app.route("/download/5y")
def download_5y():
    return send_output(
        OUTPUT_5Y
    )


@app.route("/download/2y")
def download_2y():
    return send_output(
        OUTPUT_2Y
    )


if __name__ == "__main__":
    thread = threading.Thread(
        target=run_analysis,
        name=(
            "eurgbp-candidateB-portfolio-substitution"
        ),
        daemon=True,
    )

    thread.start()

    port = int(
        os.getenv(
            "PORT",
            5000,
        )
    )

    app.run(
        host="0.0.0.0",
        port=port,
        debug=False,
    )
